// Fail-closed auth: reject unless ?t= matches VIO_WEBHOOK_TOKEN. No env set at all = reject
// everything, not "allow everything" — a forged event here could eventually reach a real call.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Dedup (idempotency via workflow static data) + TCPA warm-only gate.
// Mirrors n8n-workflows/test-reply-brain.mjs's decide() exactly — keep both in sync; that file
// is the offline proof this logic is correct and TCPA-safe BEFORE it ever runs live.
//
// Decision is "propose_call", not "call": Instantly's reply_received payload carries no phone
// number, and reach-engine deliberately never reveals one in the batch step (mobile/dial credits
// are reserved for exactly this moment). Revealing the phone and placing the call are separate,
// still human-gated steps downstream — not wired here, see the NOT WIRED node on the true branch.
const payload = $('Authenticate (fail-closed)').item.json;
const raw = $input.item.json; // OpenAi node, simplifyOutput:false -> raw chat/completions response

let sentiment = { sentiment: 'unknown', out_of_office: false };
try {
  let content = raw.choices[0].message.content || '';
  // This node type has no strict JSON-mode toggle, so defensively strip markdown fences
  // in case the model wraps its answer in ```json ... ``` despite the system prompt.
  content = content.replace(/```json|```/gi, '').trim();
  sentiment = JSON.parse(content);
} catch (e) {
  sentiment = { sentiment: 'unknown', out_of_office: false, parse_error: String(e) };
}

const data = $getWorkflowStaticData('node');
data.seenIds = data.seenIds || [];

const key = payload.email_id || null;

if (payload.event_type !== 'reply_received') {
  return { json: { decision: 'ignore', reason: `not reply_received (${payload.event_type})`, payload, sentiment } };
}
if (key && data.seenIds.includes(key)) {
  return { json: { decision: 'skip', reason: 'duplicate email_id (replay/forged)', payload, sentiment } };
}
if (key) { data.seenIds.push(key); if (data.seenIds.length > 5000) data.seenIds.shift(); }

const s = String(sentiment.sentiment || '').toLowerCase();
if (s !== 'positive') {
  return { json: { decision: 'skip', reason: `sentiment "${s}" (warm-only)`, payload, sentiment } };
}
if (sentiment.out_of_office === true) {
  return { json: { decision: 'skip', reason: 'out-of-office / auto-reply', payload, sentiment } };
}
return { json: { decision: 'propose_call', reason: 'positive + not-OOO — needs phone reveal + human approval before any call, not a call itself', payload, sentiment } };

